mapper.select:
SELECT f.*, r.name as region_name, u.username as user_name, u.avatar as user_avatar FROM food f LEFT JOIN region r ON f.region_id = r.id LEFT JOIN user u ON f.user_id = u.id WHERE f.status = 1 ORDER BY
CASE WHEN r.name = #{locationKeyword} OR r.name = CONCAT(#{locationKeyword}, '市') OR r.name = CONCAT(#{locationKeyword}, '区') OR r.name = CONCAT(#{locationKeyword}, '县') THEN 0 WHEN r.name LIKE CONCAT('%', #{locationKeyword}, '%') THEN 1 ELSE 2 END,
f.like_count DESC, f.create_time DESC LIMIT #{limit}
